namespace sv_d1e87420e9ed4f8298da70a0504d3c76.Models;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public class PersonalInfoModel
{
    public string FullName { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";
    public string Address { get; set; } = "";

    public PersonalInfo ToRecord() => new(FullName, Email, Phone, Address);
}

public class WorkEntryModel
{
    public string Company { get; set; } = "";
    public string Title { get; set; } = "";
    public DateTime? StartDate { get; set; }
    public DateTime? EndDate { get; set; }
    public bool IsCurrent { get; set; }
    public string Description { get; set; } = "";

    public WorkEntry ToRecord() => new(Company, Title, StartDate!.Value, IsCurrent ? null : EndDate, Description);
}

public class ReferenceModel
{
    public string Name { get; set; } = "";
    public string Relationship { get; set; } = "";
    public string Email { get; set; } = "";
    public string Phone { get; set; } = "";

    public Reference ToRecord() => new(Name, Relationship, Email, Phone);
}

public class CoverLetterModel
{
    public string Text { get; set; } = "";
}

using sv_d1e87420e9ed4f8298da70a0504d3c76.Models;

namespace sv_d1e87420e9ed4f8298da70a0504d3c76.Services;

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

.step-indicator {
    display: flex;
    align-items: flex-start;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    min-width: 80px;
    cursor: default;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
    transition: all 0.2s;
}

.step.current .step-circle {
    border-color: #0d6efd;
    background: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    border-color: #198754;
    background: #198754;
    color: white;
}

.step.future .step-circle {
    opacity: 0.5;
}

.step-label {
    margin-top: 0.5rem;
    font-size: 0.75rem;
    text-align: center;
    color: #6c757d;
    max-width: 90px;
}

.step.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-label {
    color: #198754;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin-top: 18px;
    min-width: 30px;
    max-width: 60px;
}

.step-connector.active {
    background: #198754;
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    <h4>Personal Information</h4>

    <div class="mb-3">
        <label class="form-label">Full Name <span class="text-danger">*</span></label>
        <input type="text" class="form-control @ValidationCss("FullName")"
               @bind="Model.FullName" @bind:event="oninput" />
        @if (errors.TryGetValue("FullName", out var fnErr))
        {
            <div class="invalid-feedback">@fnErr</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Email <span class="text-danger">*</span></label>
        <input type="email"
               class="form-control @(errors.ContainsKey("Email") || !string.IsNullOrEmpty(EmailError) ? "is-invalid" : "")"
               @bind="Model.Email" @bind:event="oninput" />
        @if (errors.TryGetValue("Email", out var emErr))
        {
            <div class="invalid-feedback">@emErr</div>
        }
        else if (!string.IsNullOrEmpty(EmailError))
        {
            <div class="invalid-feedback">@EmailError</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Phone <span class="text-danger">*</span></label>
        <input type="tel" class="form-control @ValidationCss("Phone")"
               @bind="Model.Phone" @bind:event="oninput" />
        @if (errors.TryGetValue("Phone", out var phErr))
        {
            <div class="invalid-feedback">@phErr</div>
        }
    </div>

    <div class="mb-3">
        <label class="form-label">Address <span class="text-danger">*</span></label>
        <textarea class="form-control @ValidationCss("Address")"
                  rows="2" @bind="Model.Address" @bind:event="oninput"></textarea>
        @if (errors.TryGetValue("Address", out var adErr))
        {
            <div class="invalid-feedback">@adErr</div>
        }
    </div>

    <div class="d-flex justify-content-end">
        <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
            @if (IsValidating)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Next
        </button>
    </div>
</div>

@code {
    [Parameter] public PersonalInfoModel Model { get; set; } = default!;
    [Parameter] public string? EmailError { get; set; }
    [Parameter] public bool IsValidating { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private Dictionary<string, string> errors = new();

    private string ValidationCss(string field) =>
        errors.ContainsKey(field) ? "is-invalid" : "";

    private async Task HandleNext()
    {
        errors.Clear();
        if (string.IsNullOrWhiteSpace(Model.FullName))
            errors["FullName"] = "Full name is required.";
        if (string.IsNullOrWhiteSpace(Model.Email))
            errors["Email"] = "Email is required.";
        if (string.IsNullOrWhiteSpace(Model.Phone))
            errors["Phone"] = "Phone is required.";
        if (string.IsNullOrWhiteSpace(Model.Address))
            errors["Address"] = "Address is required.";

        if (errors.Count == 0)
            await OnNext.InvokeAsync();
    }
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    <h4>Work History</h4>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        <WorkEntryForm Entry="Entries[index]" Index="index"
                       CanRemove="Entries.Count > 1"
                       OnRemove="() => RemoveEntry(index)" />
    }

    <button class="btn btn-outline-secondary mb-3" @onclick="AddEntry">
        + Add Another Position
    </button>

    @if (!string.IsNullOrEmpty(error))
    {
        <div class="alert alert-danger">@error</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<WorkEntryModel> Entries { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? error;

    private void AddEntry()
    {
        Entries.Add(new WorkEntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
            Entries.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        error = null;
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) ||
                string.IsNullOrWhiteSpace(entry.Title) ||
                entry.StartDate is null)
            {
                error = "Each position requires a company name, job title, and start date.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    <h4>References</h4>
    <p class="text-muted">Please provide 2–3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        <ReferenceForm Reference="References[index]" Index="index"
                       CanRemove="References.Count > 2"
                       OnRemove="() => RemoveReference(index)" />
    }

    @if (References.Count < 3)
    {
        <button class="btn btn-outline-secondary mb-3" @onclick="AddReference">
            + Add Reference
        </button>
    }

    @if (!string.IsNullOrEmpty(error))
    {
        <div class="alert alert-danger">@error</div>
    }

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? error;

    private void AddReference()
    {
        if (References.Count < 3)
            References.Add(new ReferenceModel());
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
            References.RemoveAt(index);
    }

    private async Task HandleNext()
    {
        error = null;
        if (References.Count < 2)
        {
            error = "At least 2 references are required.";
            return;
        }
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                error = "All reference fields are required.";
                return;
            }
        }
        await OnNext.InvokeAsync();
    }
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    <h4>Cover Letter</h4>

    <div class="mb-3">
        <textarea class="form-control" rows="10"
                  @bind="Model.Text" @bind:event="oninput"
                  maxlength="2000"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="form-text text-end">@Model.Text.Length / 2000 characters</div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public CoverLetterModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 3rem;">✅</div>
            <h4>Application Submitted!</h4>
            <p class="text-muted">Your application ID is <strong>#@ApplicationId</strong></p>
            <p>Thank you for your application. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <h4>Review & Submit</h4>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@PersonalInfo.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@PersonalInfo.Address</dd>
                </dl>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var entry = WorkEntries[i];
                    <div class="@(i < WorkEntries.Count - 1 ? "mb-3 pb-3 border-bottom" : "")">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span class="text-muted">
                            @entry.StartDate?.ToString("MMM yyyy") —
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                @for (int i = 0; i < References.Count; i++)
                {
                    var r = References[i];
                    <div class="@(i < References.Count - 1 ? "mb-2" : "")">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span class="text-muted">@r.Email · @r.Phone</span>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
            </div>
            <div class="card-body">
                <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter.Text</p>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="alert alert-danger">@SubmitError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-2"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public CoverLetterModel CoverLetter { get; set; } = default!;
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? SubmitError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models
@using sv_d1e87420e9ed4f8298da70a0504d3c76.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h3 class="mb-4">Job Application</h3>

<StepIndicator CurrentStep="currentStep"
               CompletedSteps="completedSteps"
               OnStepClicked="GoToStep" />

@switch (currentStep)
{
    case 1:
        <PersonalInfoStep Model="personalInfo"
                          EmailError="@emailError"
                          IsValidating="isValidatingEmail"
                          OnNext="HandlePersonalInfoNext" />
        break;
    case 2:
        <WorkHistoryStep Entries="workEntries"
                         OnNext="() => AdvanceStep(2)"
                         OnBack="() => GoToStep(1)" />
        break;
    case 3:
        <ReferencesStep References="references"
                        OnNext="() => AdvanceStep(3)"
                        OnBack="() => GoToStep(2)" />
        break;
    case 4:
        <CoverLetterStep Model="coverLetter"
                         OnNext="() => AdvanceStep(4)"
                         OnBack="() => GoToStep(3)" />
        break;
    case 5:
        <ReviewStep PersonalInfo="personalInfo"
                    WorkEntries="workEntries"
                    References="references"
                    CoverLetter="coverLetter"
                    IsSubmitting="isSubmitting"
                    IsSubmitted="isSubmitted"
                    ApplicationId="applicationId"
                    SubmitError="@submitError"
                    OnBack="() => GoToStep(4)"
                    OnSubmit="HandleSubmit"
                    OnEditStep="GoToStep" />
        break;
}

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private CoverLetterModel coverLetter = new();

    private string? emailError;
    private bool isValidatingEmail;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;
        isValidatingEmail = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!valid)
            {
                emailError = "This email address is not valid.";
                return;
            }
            AdvanceStep(1);
        }
        finally
        {
            isValidatingEmail = false;
        }
    }

    private void AdvanceStep(int fromStep)
    {
        completedSteps.Add(fromStep);
        currentStep = fromStep + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
