@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    <h4>Cover Letter</h4>

    <div class="mb-3">
        <textarea class="form-control" rows="10"
                  @bind="Model.Text" @bind:event="oninput"
                  maxlength="2000"
                  placeholder="Write your cover letter here..."></textarea>
        <div class="form-text text-end">@Model.Text.Length / 2000 characters</div>
    </div>

    <div class="d-flex justify-content-between">
        <button class="btn btn-secondary" @onclick="OnBack">Back</button>
        <button class="btn btn-primary" @onclick="OnNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public CoverLetterModel Model { get; set; } = default!;
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
}

@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models

<div class="step-content">
    @if (IsSubmitted)
    {
        <div class="text-center py-5">
            <div class="mb-3" style="font-size: 3rem;">✅</div>
            <h4>Application Submitted!</h4>
            <p class="text-muted">Your application ID is <strong>#@ApplicationId</strong></p>
            <p>Thank you for your application. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <h4>Review & Submit</h4>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Personal Information</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(1)">Edit</button>
            </div>
            <div class="card-body">
                <dl class="row mb-0">
                    <dt class="col-sm-3">Name</dt>
                    <dd class="col-sm-9">@PersonalInfo.FullName</dd>
                    <dt class="col-sm-3">Email</dt>
                    <dd class="col-sm-9">@PersonalInfo.Email</dd>
                    <dt class="col-sm-3">Phone</dt>
                    <dd class="col-sm-9">@PersonalInfo.Phone</dd>
                    <dt class="col-sm-3">Address</dt>
                    <dd class="col-sm-9">@PersonalInfo.Address</dd>
                </dl>
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Work History</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(2)">Edit</button>
            </div>
            <div class="card-body">
                @for (int i = 0; i < WorkEntries.Count; i++)
                {
                    var entry = WorkEntries[i];
                    <div class="@(i < WorkEntries.Count - 1 ? "mb-3 pb-3 border-bottom" : "")">
                        <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                        <span class="text-muted">
                            @entry.StartDate?.ToString("MMM yyyy") —
                            @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy"))
                        </span>
                        @if (!string.IsNullOrWhiteSpace(entry.Description))
                        {
                            <p class="mt-1 mb-0">@entry.Description</p>
                        }
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>References</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(3)">Edit</button>
            </div>
            <div class="card-body">
                @for (int i = 0; i < References.Count; i++)
                {
                    var r = References[i];
                    <div class="@(i < References.Count - 1 ? "mb-2" : "")">
                        <strong>@r.Name</strong> (@r.Relationship)<br />
                        <span class="text-muted">@r.Email · @r.Phone</span>
                    </div>
                }
            </div>
        </div>

        <div class="card mb-3">
            <div class="card-header d-flex justify-content-between align-items-center">
                <strong>Cover Letter</strong>
                <button class="btn btn-link btn-sm p-0" @onclick="() => OnEditStep.InvokeAsync(4)">Edit</button>
            </div>
            <div class="card-body">
                <p class="mb-0" style="white-space: pre-wrap;">@CoverLetter.Text</p>
            </div>
        </div>

        @if (!string.IsNullOrEmpty(SubmitError))
        {
            <div class="alert alert-danger">@SubmitError</div>
        }

        <div class="d-flex justify-content-between">
            <button class="btn btn-secondary" @onclick="OnBack">Back</button>
            <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
                @if (IsSubmitting)
                {
                    <span class="spinner-border spinner-border-sm me-2"></span>
                    <span>Submitting…</span>
                }
                else
                {
                    <span>Submit Application</span>
                }
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public PersonalInfoModel PersonalInfo { get; set; } = default!;
    [Parameter] public List<WorkEntryModel> WorkEntries { get; set; } = default!;
    [Parameter] public List<ReferenceModel> References { get; set; } = default!;
    [Parameter] public CoverLetterModel CoverLetter { get; set; } = default!;
    [Parameter] public bool IsSubmitting { get; set; }
    [Parameter] public bool IsSubmitted { get; set; }
    [Parameter] public int? ApplicationId { get; set; }
    [Parameter] public string? SubmitError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnSubmit { get; set; }
    [Parameter] public EventCallback<int> OnEditStep { get; set; }
}

@page "/apply"
@rendermode InteractiveServer
@using sv_d1e87420e9ed4f8298da70a0504d3c76.Models
@using sv_d1e87420e9ed4f8298da70a0504d3c76.Services
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<h3 class="mb-4">Job Application</h3>

<StepIndicator CurrentStep="currentStep"
               CompletedSteps="completedSteps"
               OnStepClicked="GoToStep" />

@switch (currentStep)
{
    case 1:
        <PersonalInfoStep Model="personalInfo"
                          EmailError="@emailError"
                          IsValidating="isValidatingEmail"
                          OnNext="HandlePersonalInfoNext" />
        break;
    case 2:
        <WorkHistoryStep Entries="workEntries"
                         OnNext="() => AdvanceStep(2)"
                         OnBack="() => GoToStep(1)" />
        break;
    case 3:
        <ReferencesStep References="references"
                        OnNext="() => AdvanceStep(3)"
                        OnBack="() => GoToStep(2)" />
        break;
    case 4:
        <CoverLetterStep Model="coverLetter"
                         OnNext="() => AdvanceStep(4)"
                         OnBack="() => GoToStep(3)" />
        break;
    case 5:
        <ReviewStep PersonalInfo="personalInfo"
                    WorkEntries="workEntries"
                    References="references"
                    CoverLetter="coverLetter"
                    IsSubmitting="isSubmitting"
                    IsSubmitted="isSubmitted"
                    ApplicationId="applicationId"
                    SubmitError="@submitError"
                    OnBack="() => GoToStep(4)"
                    OnSubmit="HandleSubmit"
                    OnEditStep="GoToStep" />
        break;
}

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();

    private PersonalInfoModel personalInfo = new();
    private List<WorkEntryModel> workEntries = [new()];
    private List<ReferenceModel> references = [new(), new()];
    private CoverLetterModel coverLetter = new();

    private string? emailError;
    private bool isValidatingEmail;
    private bool isSubmitting;
    private bool isSubmitted;
    private int? applicationId;
    private string? submitError;

    private async Task HandlePersonalInfoNext()
    {
        emailError = null;
        isValidatingEmail = true;
        try
        {
            var valid = await ApplicationService.ValidateEmailAsync(personalInfo.Email);
            if (!valid)
            {
                emailError = "This email address is not valid.";
                return;
            }
            AdvanceStep(1);
        }
        finally
        {
            isValidatingEmail = false;
        }
    }

    private void AdvanceStep(int fromStep)
    {
        completedSteps.Add(fromStep);
        currentStep = fromStep + 1;
    }

    private void GoToStep(int step)
    {
        currentStep = step;
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        try
        {
            var application = new JobApplication(
                personalInfo.ToRecord(),
                new WorkHistory(workEntries.Select(e => e.ToRecord()).ToList()),
                references.Select(r => r.ToRecord()).ToList(),
                coverLetter.Text
            );
            applicationId = await ApplicationService.SubmitApplicationAsync(application);
            isSubmitted = true;
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }
}

